import {
  Object3D,
  Mesh,
  PlaneGeometry,
  Vector2,
} from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import { createText } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{position: [number, number, number], rotation: [number, number, number], scale: [number, number, number]}} transform
 * @property {{imageUrl: string}} assets
 * @property {{textContent: string}} text
 * @property {any[]} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {{textureLoader: {load: (url: string) => import('three').Texture}}} textureLoader
 * @property {{primitives: Record<string, Function>}} primitives
 * @property {{fontAtlas: any}} fontAtlas
 */

/**
 * Creates a UI node: a textured plane with MSDF text overlay.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
  // Root container
  const root = new Object3D();

  // Apply transform
  const [px, py, pz] = config.transform?.position ?? [0, 0, 0];
  const [rx, ry, rz] = config.transform?.rotation ?? [0, 0, 0];
  const [sx, sy, sz] = config.transform?.scale ?? [1, 1, 1];
  root.position.set(px, py, pz);
  root.rotation.set(rx, ry, rz);
  root.scale.set(sx, sy, sz);

  // -------------------------------------------------------------------------
  // Textured plane
  // -------------------------------------------------------------------------
  const tex = ctx.textureLoader.load(config.assets.imageUrl);
  // Ensure the texture repeats (useful for atlas UVs if needed)
  tex.wrapS = tex.wrapT = tex.repeat ? tex.repeat : tex.wrapS;
  tex.needsUpdate = true;

  const planeMaterial = new MeshBasicNodeMaterial({
    map: tex,
    transparent: true,
    depthWrite: false,
  });

  // Use a unit plane; aspect ratio can be adjusted later if required
  const planeGeometry = new PlaneGeometry(1, 1);
  const planeMesh = new Mesh(planeGeometry, planeMaterial);
  // Center the plane on its local origin
  planeMesh.position.set(0, 0, 0);
  root.add(planeMesh);

  // -------------------------------------------------------------------------
  // MSDF Text overlay
  // -------------------------------------------------------------------------
  const textString = config.text?.textContent ?? '';
  const textNode = createText(textString, {
    // Use the design token “display” typographic style (headline size)
    font: ctx.fontAtlas.getFont('display'), // assumed accessor
    fontSize: 0.34, // headline scale from design system (scene‑units)
    color: '#16161d', // ink
    // Align text to the centre of the plane
    anchor: new Vector2(0.5, 0.5),
    // Slightly in front of the plane to avoid z‑fighting
    offsetZ: 0.001,
  }, ctx);
  root.add(textNode);

  // -------------------------------------------------------------------------
  // Apply cinematic primitives (none for this node, but keep hook)
  // -------------------------------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === 'function') {
        fn(root, primitive.params);
      }
    }
  }

  // -------------------------------------------------------------------------
  // Event handlers placeholder (no interactions defined)
  // -------------------------------------------------------------------------
  root.userData.handlers = {};

  // -------------------------------------------------------------------------
  // Cleanup routine
  // -------------------------------------------------------------------------
  root.userData.cleanup = () => {
    // Dispose geometry & material
    planeGeometry.dispose();
    planeMaterial.dispose();
    tex.dispose();

    // Dispose text resources (assumed dispose method)
    if (typeof textNode.userData?.cleanup === 'function') {
      textNode.userData.cleanup();
    }

    // Kill any GSAP timelines (none created here, but purge just in case)
    gsap.globalTimeline.clear();
  };

  return root;
}
